/**
 * Rasterise the brand marks into the favicon, app icon and share card.
 *
 * Everything here derives from the vector exports in public/brand/, which came
 * from Figma. Nothing is redrawn: the only operations are rasterise, resize and
 * compose onto a ground. Re-run after any logo change.
 *
 * Outputs land on Next's file conventions, so the <link> and <meta> tags are
 * generated by the framework with correct sizes and types rather than
 * hand-written and left to rot:
 *
 *   src/app/icon.svg              vector favicon, modern browsers
 *   src/app/favicon.ico           16/32/48, for crawlers and older clients
 *   src/app/apple-icon.png        180, iOS home screen
 *   src/app/opengraph-image.png   1200x630 share card
 *   public/icons/icon-{192,512}.png        web app manifest
 *   public/icons/icon-maskable-512.png     Android adaptive icon
 *
 * Run: node scripts/build-app-icons.mjs
 */
import { readFileSync, writeFileSync, mkdirSync, copyFileSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import sharp from "sharp";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const BRAND = join(ROOT, "public/brand");
const APP = join(ROOT, "src/app");
const ICONS = join(ROOT, "public/icons");

const MARK = join(BRAND, "tradl-app-mark.svg");
const WORDMARK = join(BRAND, "tradl-wordmark.svg");
const TAGLINE = join(BRAND, "tradl-tagline.svg");

/** The wordmark's own ink, used as the bleed behind the maskable icon. */
const INK = "#010101";

/**
 * The page ground, read from the stylesheet rather than repeated here. The share
 * card should always sit on the same ground as the site, and two copies of a hex
 * value drift the moment one of them is edited.
 */
const GROUND = (() => {
  const css = readFileSync(join(ROOT, "src/design-system/marketing/ground.css"), "utf8");
  const m = css.match(/--page-ground:\s*([^;]+);/);
  if (!m) throw new Error("could not read --page-ground from marketing/ground.css");
  return m[1].trim();
})();

/** Recolour a single-ink vector. Used to put the wordmark on a dark ground. */
const recolour = (file, to) =>
  Buffer.from(
    readFileSync(file, "utf8").replaceAll('fill="#010101"', `fill="${to}"`).replaceAll('fill="black"', `fill="${to}"`)
  );

/** Rasterise at high density first so curves stay clean at small sizes. */
const render = (file, size) =>
  sharp(file, { density: 1200 }).resize(size, size, { fit: "contain", background: "#00000000" }).png();

mkdirSync(ICONS, { recursive: true });

/* ---------------------------------------------------------------------------
   Vector favicon. Copied rather than regenerated: it is already the right
   thing, and browsers that support SVG favicons get the sharpest result at
   every size for 1.2KB.
   ------------------------------------------------------------------------- */
copyFileSync(MARK, join(APP, "icon.svg"));

/* ---------------------------------------------------------------------------
   Raster sizes.
   ------------------------------------------------------------------------- */
await render(MARK, 180).toFile(join(APP, "apple-icon.png"));
await render(MARK, 192).toFile(join(ICONS, "icon-192.png"));
await render(MARK, 512).toFile(join(ICONS, "icon-512.png"));

/* Maskable icons are cropped to a circle by the launcher, so the artwork has to
   sit inside a safe zone of roughly 80 per cent. The mark is a rounded square
   filling its whole canvas, which would lose its corners, so it is inset onto
   its own ink as the bleed colour. */
const MASKABLE = 512;
const SAFE = Math.round(MASKABLE * 0.62);
const maskArt = await render(MARK, SAFE).toBuffer();
await sharp({
  create: { width: MASKABLE, height: MASKABLE, channels: 4, background: INK },
})
  .composite([{ input: maskArt, gravity: "centre" }])
  .png()
  .toFile(join(ICONS, "icon-maskable-512.png"));

/* ---------------------------------------------------------------------------
   favicon.ico

   sharp has no ICO encoder, so the container is written by hand. Modern ICO
   allows PNG payloads, which is what every current consumer reads, so each
   entry is just a PNG with a 16-byte directory record in front of it.

   Format: ICONDIR (6 bytes) then one ICONDIRENTRY (16 bytes) per size, then the
   image data. A width or height byte of 0 means 256.
   ------------------------------------------------------------------------- */
const ICO_SIZES = [16, 32, 48];
const pngs = await Promise.all(ICO_SIZES.map((s) => render(MARK, s).toBuffer()));

const header = Buffer.alloc(6);
header.writeUInt16LE(0, 0); // reserved
header.writeUInt16LE(1, 2); // 1 = icon
header.writeUInt16LE(ICO_SIZES.length, 4);

let offset = 6 + 16 * ICO_SIZES.length;
const entries = ICO_SIZES.map((size, i) => {
  const e = Buffer.alloc(16);
  e.writeUInt8(size >= 256 ? 0 : size, 0); // width
  e.writeUInt8(size >= 256 ? 0 : size, 1); // height
  e.writeUInt8(0, 2); // palette size, 0 for truecolour
  e.writeUInt8(0, 3); // reserved
  e.writeUInt16LE(1, 4); // colour planes
  e.writeUInt16LE(32, 6); // bits per pixel
  e.writeUInt32LE(pngs[i].length, 8);
  e.writeUInt32LE(offset, 12);
  offset += pngs[i].length;
  return e;
});

writeFileSync(join(APP, "favicon.ico"), Buffer.concat([header, ...entries, ...pngs]));

/* ---------------------------------------------------------------------------
   Share card, 1200x630, on the site's own dark ground.

   Built from the wordmark and the tagline rather than the full lockup. The
   lockup cannot be inverted: its app tile is #010101 with a white letterform
   inside it, so recolouring the ink to white produces a white tile holding a
   white "t". Dropping the tile and recolouring the two single-ink vectors gives
   a correct dark card with no redrawing.

   Deliberately no live text. Rendering a headline would need a font bundled or
   fetched at build time, and the tagline already carries the descriptor as
   outlined paths. It also keeps the card to one tagline, which doc 01 §10
   requires: the headline and the doctrine line live in the meta tags, where
   copy belongs and where it stays selectable.
   ------------------------------------------------------------------------- */
const OG = { width: 1200, height: 630 };

const WORDMARK_W = 560;
const WORDMARK_RATIO = 103 / 327; // from the export's viewBox
/* The lockup sets the tagline to about 79 per cent of the wordmark's width.
   Keeping that ratio means the card matches the drawn relationship rather than
   an eyeballed one. */
const TAGLINE_W = Math.round(WORDMARK_W * 0.79);
const TAGLINE_RATIO = 13 / 258;
const GAP = 28;

const wordmarkH = Math.round(WORDMARK_W * WORDMARK_RATIO);
const taglineH = Math.round(TAGLINE_W * TAGLINE_RATIO);

const wordmarkPng = await sharp(recolour(WORDMARK, "#FFFFFF"), { density: 1200 })
  .resize(WORDMARK_W, wordmarkH, { fit: "contain", background: "#00000000" })
  .png()
  .toBuffer();

const taglinePng = await sharp(recolour(TAGLINE, "#FFFFFF"), { density: 1200 })
  .resize(TAGLINE_W, taglineH, { fit: "contain", background: "#00000000" })
  .png()
  .toBuffer();

const blockH = wordmarkH + GAP + taglineH;
const top = Math.round((OG.height - blockH) / 2);

await sharp({ create: { ...OG, channels: 4, background: GROUND } })
  .composite([
    { input: wordmarkPng, top, left: Math.round((OG.width - WORDMARK_W) / 2) },
    { input: taglinePng, top: top + wordmarkH + GAP, left: Math.round((OG.width - TAGLINE_W) / 2) },
  ])
  .png()
  .toFile(join(APP, "opengraph-image.png"));

console.log("app icons written:");
console.log("  src/app/icon.svg, favicon.ico, apple-icon.png, opengraph-image.png");
console.log("  public/icons/icon-192.png, icon-512.png, icon-maskable-512.png");
